edits.before:
const navigate = config.resultsList.navigation || navigation;
/**
 * @listens {keydown} Listens to all `keydown` events on the input field
 **/
config.inputField.addEventListener("keydown", navigate);

edits.after:
const navigateFn = config.resultsList.navigation || navigation;
// Remove previous listener if exists
if (config.inputField._autoCompleteNavigateListener) {
  config.inputField.removeEventListener("keydown", config.inputField._autoCompleteNavigateListener);
}
config.inputField.addEventListener("keydown", navigateFn);
config.inputField._autoCompleteNavigateListener = navigateFn;
